function mirrorCallsign(text) {
    let cleaned = "";
    for (const symbol of text)
        if (/[a-z0-9]/i.test(symbol))
            cleaned += symbol.toLowerCase();
    let reversed = "";
    for (let i = cleaned.length - 1; i >= 0; i--)
        reversed += cleaned[i];
    return cleaned === reversed;
}

function mirrorCallsign(text) {
    const counts = (symbol) => /[a-z0-9]/i.test(symbol);
    let left = 0;
    let right = text.length - 1;
    while (left < right) {
        if (!counts(text[left])) {
            left++;
        } else if (!counts(text[right])) {
            right--;
        } else {
            if (text[left].toLowerCase() !== text[right].toLowerCase())
                return false;
            left++;
            right--;
        }
    }
    return true;
}
